use super::*;
use crate::typed_operation_page::ResultPageDelivery;
use semio_framework_value::{FromValue,ToValue};
thread_local!{static BANK:std::cell::RefCell<semio_framework_value_testing_admission::EffectBank>=std::cell::RefCell::new(semio_framework_value_testing_admission::EffectBank::new(semio_framework_value_testing_admission::Wallet::new(RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<30,maximum_release_bytes:1<<30,maximum_depth:1<<20},1<<40)));}
fn observe<T>(body:impl FnOnce()->T)->(T,semio_framework_trace::HeapAllocationObservation){BANK.with(|_|());semio_framework_trace::observe_heap_allocations_on_this_thread(body)}
fn fx<T>(grant:RetainedCloneGrant,run:impl FnOnce(&mut semio_framework_value::RetainedAllocationEffect<'_>)->T)->T{BANK.with(|bank|{let mut bank=bank.borrow_mut();let mut run=Some(run);let mut slot=None;let(poll,_)=semio_framework_value_testing_admission::driven::<ValueError>(&mut bank,RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<30,maximum_release_bytes:1<<30,maximum_depth:1<<20},1<<20,|effect,reply,_|{slot=Some((run.take().expect("single driven action"))(&mut effect.nested(grant)));Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))});match poll{semio_framework_value::RetainedWorkPoll::Complete(turn)=>turn.result.expect("driven action"),_=>panic!("driven action stayed pending")};slot.take().expect("driven action ran")})}

fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:2,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn rows(case:&serde_json::Value)->Vec<semio_framework_diagnostic::Diagnostic>{let mut value=case.clone();let object=value.as_object_mut().unwrap();object.remove("name");let pattern=object.remove("pattern").unwrap();let repeat=object.remove("repeat").unwrap().as_u64().unwrap()as usize;object.insert("message".into(),serde_json::Value::String(pattern.as_str().unwrap().repeat(repeat)));if object["expected"].is_null(){object.remove("expected");}vec![semio_framework_diagnostic::Diagnostic::from_value(serde_json::from_value(value).unwrap()).unwrap()]}
fn close(owner:&mut OperationDiagnosticPublication){owner.begin_close();let mut turns=0;while !owner.terminal_is_empty(){let g=grant(owner.next_demand(32).unwrap());let(step,heap)=observe(||fx(g,|e|owner.advance(e)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));turns+=1;assert!(turns<100000,"original diagnostic closure stalled");}}

/// 📬️ Original diagnostic bytes and five-field ACK custody survive every physical refusal and streaming window.
#[test]
fn operation_diagnostics_original_pages_preserve_ack_custody_and_physical_receipts(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for case in corpus["cases"].as_array().unwrap(){
  let mut input=rows(case);let vector=input.as_ptr();let body=input[0].message.as_ptr();let expected=serde_json::to_value(input[0].to_value()).unwrap();let birth=grant(OperationDiagnosticPublication::capture_demand());
  for denied in[RetainedCloneGrant{maximum_items:0,..birth},RetainedCloneGrant{maximum_copy_bytes:birth.maximum_copy_bytes-1,..birth},RetainedCloneGrant{maximum_depth:0,..birth}]{let(result,heap)=observe(||OperationDiagnosticPublication::capture(input,denied));input=match result{Err((_,rows))=>rows,Ok(_)=>panic!("denied capture admitted originals")};assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(input.as_ptr(),vector);assert_eq!(input[0].message.as_ptr(),body);}
  let((mut owner,receipt),heap)=observe(||OperationDiagnosticPublication::capture(input,birth).unwrap_or_else(|(error,_)|panic!("{error}")));assert!(receipt.fits(birth));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  let mut output=Vec::new();let mut sequence=0u32;let mut pages=0usize;let mut turns=0usize;
  while !owner.terminal_is_empty(){
   if owner.page_ready(){let token=TypedOperationResultToken{receiver:1,operation:7,generation:2,sequence,attempt:0};let g=grant(owner.page_demand().unwrap());let denied=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-1,..g};let(result,heap)=observe(||owner.take_page(token,denied).unwrap());assert!(result.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let((mut page,progress),heap)=observe(||owner.take_page(token,g).unwrap().unwrap());assert!(progress.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(page.lane,TypedOperationResultLane::Diagnostic);assert!(page.bytes().len()<=4096);assert_eq!(u32::from_le_bytes(page.bytes()[..4].try_into().unwrap()),0);output.extend_from_slice(&page.bytes()[5..]);assert_eq!(owner.original_rows().unwrap().as_ptr(),vector);assert_eq!(owner.original_rows().unwrap()[0].message.as_ptr(),body);
    for wrong in[TypedOperationResultToken{receiver:2,..token},TypedOperationResultToken{operation:8,..token},TypedOperationResultToken{generation:3,..token},TypedOperationResultToken{sequence:sequence+1,..token},TypedOperationResultToken{attempt:1,..token}]{assert!(!owner.acknowledge(wrong));assert_eq!(owner.original_rows().unwrap().as_ptr(),vector);}let pointer=page.bytes().as_ptr();let mut receiver=None;while receiver.is_none(){let d=page.presentation_demand().unwrap();assert!(d.copy_bytes<=16384&&d.capacity_bytes<=4096);let g=grant(d);for denied in denied_grants(d,g){let((next,p),heap)=observe(||fx(denied,|e|page.present(e)).unwrap());assert!(next.is_none());assert_eq!(p,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(page.bytes().as_ptr(),pointer);}let((next,p),heap)=observe(||fx(g,|e|page.present(e)).unwrap());assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert_eq!(page.bytes().as_ptr(),pointer);receiver=next;}let receiver=receiver.unwrap();assert_eq!(receiver.bytes().as_ptr(),pointer);let mut slot=Some(receiver);let d=ResultPageDelivery::capture_demand();assert!(d.copy_bytes<=4096);let g=grant(d);for denied in denied_grants(d,g){let(result,heap)=observe(||ResultPageDelivery::capture(&mut slot,denied).unwrap());assert!(result.is_none());assert_eq!(slot.as_ref().unwrap().bytes().as_ptr(),pointer);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let((mut delivery,p),heap)=observe(||ResultPageDelivery::capture(&mut slot,g).unwrap().unwrap());assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(slot.is_none());let d=delivery.next_demand(4096).unwrap();let g=grant(d);for denied in denied_grants(d,g){let(step,heap)=observe(||fx(denied,|e|delivery.advance(e)).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(step,heap)=observe(||fx(g,|e|delivery.advance(e)).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(delivery.body().unwrap().as_ptr(),pointer);assert_eq!(delivery.token(),Some(token));let header=delivery.header().unwrap();let magic=TypedOperationResultPage::RENDERER_PAGE_MAGIC.len();assert_eq!(&header[..magic],TypedOperationResultPage::RENDERER_PAGE_MAGIC);assert_eq!(header[magic+25],15);assert_eq!(u32::from_le_bytes(header[magic+26..].try_into().unwrap())as usize,page.bytes().len());let d=delivery.descriptor_demand().unwrap();let g=grant(d);for denied in denied_grants(d,g){let(result,heap)=observe(||delivery.take_descriptor(denied).unwrap());assert!(result.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(delivery.body().unwrap().as_ptr(),pointer);}let((mut descriptor,p),heap)=observe(||delivery.take_descriptor(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(delivery.terminal_is_empty());assert_eq!(descriptor.body().unwrap().as_ptr(),pointer);close_delivery(&mut descriptor);assert!(owner.acknowledge(token));assert!(!owner.acknowledge(token));close_page(&mut page);sequence+=1;pages+=1;
   }else{let d=owner.next_demand(32).unwrap();assert!(d.copy_bytes<=16384&&d.capacity_bytes<=4096&&d.release_bytes<=262144&&d.depth<=4096);let g=grant(d);let mut denials=vec![RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}];if d.copy_bytes>0{denials.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g})}if d.capacity_bytes>0{denials.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g})}if d.release_bytes>0{denials.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g})}for denied in denials{let(step,heap)=observe(||fx(denied,|e|owner.advance(e)).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(step,heap)=observe(||fx(g,|e|owner.advance(e)).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
   turns+=1;assert!(turns<100000,"original diagnostic publication stalled");
  }
  assert_eq!(serde_json::from_slice::<serde_json::Value>(&output).unwrap(),expected);if case["repeat"].as_u64().unwrap()>1{assert!(pages>1)}let(_,heap)=observe(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 }
}

/// 🛑️ Encoding cancellation returns the same original diagnostic owners through funded closure.
#[test]
fn operation_diagnostics_cancel_every_original_frontier(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for cut in corpus["cancelFrontiers"].as_array().unwrap(){let input=rows(&corpus["cases"][2]);let pointer=input[0].message.as_ptr();let(mut owner,_)=OperationDiagnosticPublication::capture(input,grant(OperationDiagnosticPublication::capture_demand())).unwrap_or_else(|(error,_)|panic!("{error}"));for _ in 0..cut.as_u64().unwrap(){let g=grant(owner.next_demand(32).unwrap());fx(g,|e|owner.advance(e)).unwrap();assert_eq!(owner.original_rows().unwrap()[0].message.as_ptr(),pointer);}close(&mut owner);let(_,heap)=observe(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}}

/// 🎟️ The production original driver copy quantum funds capture without enlarging any other currency.
#[test]
fn operation_diagnostics_original_capture_demand_fits_production_driver(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let copy=law["originalDriver"]["maximumCopyBytes"].as_u64().unwrap()as usize;
 assert_eq!(copy,16384);assert!(OperationDiagnosticPublication::capture_demand().copy_bytes<=copy,"original diagnostic capture exceeds the production original driver copy authority");
}

/// ♻️ Physical page closure reports the original actual allocator receipt on every turn.
fn close_page(page:&mut TypedOperationResultPage){let mut turns=0;while !page.terminal_is_empty(){let d=page.next_close_demand(4096).unwrap();assert!(d.copy_bytes<=16384&&d.capacity_bytes<=4096&&d.release_bytes<=262144&&d.depth<=4096);let g=grant(d);for denied in denied_grants(d,g){let quote=page.next_close_demand(denied.maximum_copy_bytes).unwrap();if denied.maximum_items>0&&quote.copy_bytes<=denied.maximum_copy_bytes&&quote.capacity_bytes<=denied.maximum_capacity_bytes&&quote.release_bytes<=denied.maximum_release_bytes&&quote.depth<=denied.maximum_depth{continue}let(step,heap)=observe(||fx(denied,|e|page.close_step(e)).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(step,heap)=observe(||fx(g,|e|page.close_step(e)).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));turns+=1;assert!(turns<10000,"physical original page closure stalled");}}
fn denied_grants(d:RetirementDemand,g:RetainedCloneGrant)->Vec<RetainedCloneGrant>{let mut denied=vec![RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}];if d.copy_bytes>0{denied.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g});}if d.capacity_bytes>0{denied.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g});}if d.release_bytes>0{denied.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g});}denied}
fn close_delivery(delivery:&mut ResultPageDelivery){delivery.begin_close();let mut turns=0;while !delivery.terminal_is_empty(){let d=delivery.next_close_demand(4096).unwrap();assert!(d.copy_bytes<=16384&&d.capacity_bytes<=4096&&d.release_bytes<=262144&&d.depth<=4096);let g=grant(d);for denied in denied_grants(d,g){let(step,heap)=observe(||fx(denied,|e|delivery.close_step(e)).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(step,heap)=observe(||fx(g,|e|delivery.close_step(e)).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));turns+=1;assert!(turns<10000,"original descriptor alias closure stalled");}}